    { sku: 'B-2', title: 'Plain widget', amountCents: 999, placedAtMs: Date.UTC(2026, 7, 29) },
  ])
  const expected = [
    'SKU,Title,Amount,Date',
    'A-1,"He said ""hi""","12,345.67",2026-08-28',
    'B-2,Plain widget,9.99,2026-08-29',
